Lemma tok_suffix_off : forall SP i sbs, 0 <= SP -> tok_suffix SP (SP + Z.of_nat i) sbs = skipn i (zbytes sbs).
Proof. intros SP i sbs H. unfold tok_suffix. rewrite zbytes_skipn. f_equal. lia. Qed.

Definition vl_post_v (v : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (if v then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' LST (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
    /\ bytes_at asegs m' SP sbs
    /\ ACONST m' /\ stack0 m' lo shi.

(* [comment removed for export] *)
Definition vl_side (m : mem) (lo shi LST SP n : Z) : Prop := aside m lo shi [(SP, n); (LST, 16)] [].

Lemma vl_side_now : forall m m1 lo shi hi LST SP n,
  vl_side m lo shi LST SP n -> munch [(lo, hi)]%Z m m1 -> wmono asegs m m1 -> aceil <= lo ->
  ACONST m1 /\ stack0 m1 lo shi /\ accessible m1 SP n /\ accessible m1 LST 16.
Proof.
  intros m m1 lo shi hi LST SP n S MU WM CEIL.
  assert (S1 : aside m1 lo shi [(SP, n); (LST, 16)] [])
    by (eapply aside_transport; [exact S| exact MU| exact WM| apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_nil]]).
  destruct S1 as (AC & SK & FA & _). split; [exact AC|]. split; [exact SK|].
  split; [exact (Forall_inv FA)| exact (Forall_inv (Forall_inv_tail FA))].
Qed.

(* [comment removed for export] *)
Definition vl_ctx (m m1 : mem) (sp s0v rav : word) (j8 : list byte) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo shi : Z)
    (obj : list cell) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -64) [CB 8 j8]
  /\ rw_cells asegs m1 (bv_unsigned sp + -56) obj
  /\ rw_cells asegs m1 (bv_unsigned sp + -16) [C8 s0v; C8 rav]
  /\ rw_cells asegs m1 LST (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
  /\ bytes_at asegs m1 SP sbs
  /\ stk asegs m1 lo (bv_unsigned sp + -64)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ vl_side m lo shi LST SP (Z.of_nat (length sbs)).

Definition vl_pure (sp : word) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo shi : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64 /\ lo + VALIDATE_LIST_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= LST \/ LST + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)) <= lo)
  /\ (bv_unsigned sp <= SP \/ SP + Z.of_nat (length sbs) <= lo)
  /\ bv_unsigned sp mod 16 = 0 /\ bv_unsigned sp + 64 <= shi /\ LST mod 8 = 0.

Local Ltac open_vctx CTX PURE :=
  lazymatch type of CTX with vl_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (FR0 & OBJ & FRhi & LSV & WIN & ST & MU & WM & MI & SD);
  destruct PURE as (SP64 & LO & CEIL & SEPL & SEPW & SPAL & SHI & LAL);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (rw_cells_bound _ _ _ _ LSV) as LB; cbn [cells_size csize Nat.add length] in LB, SEPL;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPL; hydeL SEPW; hydeL SPAL; hydeL LAL;
  unfold OptItCells, VALIDATE_LIST_STACK, TOKIT_STACK, AINTRIN_STACK in * end.

