Lemma vl_exit : forall (v : bool) rax ra sp gp tp t0 t1 t2 s0x a1x a2 a3 a4 a5 a6 a7 s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (j8 : list byte)
    (F : bvmap 5 word) fc (m m1 : mem) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo shi : Z)
    (it vp vl err : Z) (pad7 : list byte),
  vl_ctx m m1 sp s0v ra j8 LST SP sbs lrest lo shi (OptItCells LST it vp vl err pad7) -> vl_pure sp LST SP sbs lrest lo shi ->
  evt asegs (vl_post_v v ra sp gp tp s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LST SP sbs lrest lo shi m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 s0x s1 (wz (if v then 1 else 0)) a1x a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xd2efc) fc None m1 (seg_rom asegs)).
Proof.
  intros until pad7. intros CTX PURE. open_vctx CTX PURE. unfold wz.
  (* [comment removed for export] *)
  step. step.
  join_frameA OBJ FRhi (bv_unsigned sp + -56). join_frameA FR0 OBJ (bv_unsigned sp + -64).
  step. release_frame FR0 ST (bv_unsigned sp). step.
  destruct (vl_side_now _ _ _ _ _ _ _ _ SD MU WM CEIL) as (AC4 & SK4 & _).
  finish.
Qed.

Local Ltac vl_rebuild_ctx m sp :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR0 : rw_cells _ mx (bv_unsigned sp + -64) [CB 8 ?j8],
    OBJ : rw_cells _ mx (bv_unsigned sp + -56) ?ob, FRhi : rw_cells _ mx (bv_unsigned sp + -16) [C8 ?s0v; C8 ?rav],
    LSV : rw_cells _ mx ?LST (C8 _ :: C8 _ :: ?lrest), WIN : bytes_at _ mx ?SP ?sbs, ST : stk _ mx ?lo _,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx, SD : vl_side m _ ?shi _ _ _ |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : vl_ctx m mx sp s0v rav j8 LST SP sbs lrest lo shi ob)
        by (unfold vl_ctx; repeat (split; [eassumption|]); eassumption)
  end end.

(* [comment removed for export] *)
Local Ltac vl_call_incr sp LST it vp vl err SP pad7 sbs lrest lo shi OBJ LSV WIN ST SD MU WM CEIL SPAL LAL LO SHI SEPL SEPW :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let ACc := fresh "ACc" in let SKc := fresh "SKc" in let AWc := fresh "AWc" in let ALc := fresh "ALc" in
    let AOc := fresh "AOc" in
    destruct (vl_side_now _ mc _ _ _ _ _ _ SD MU WM CEIL) as (ACc & SKc & AWc & ALc);
    assert (AOc : aobj mc (bv_unsigned sp + -56) SZ_TOKIT)
      by (eapply (aobj_stack mc lo shi); [exact SKc| clear - LO; lia| unfold SZ_TOKIT; clear; lia| unfold SZ_TOKIT; clear - SHI; lia]);
    let S := fresh "OS" in
    pose proof OPTINC as S;
    unfold optit_incr_stmt, optit_incr_post, SZ_TOKIT, TOKIT_STACK, AINTRIN_STACK, P_A_OPT_TOKEN_LIST_INCR in S;
    callZc (S (bv_unsigned sp + -56) LST it vp vl err SP lo pad7 sbs lrest) (clear S OBJ LSV WIN ST);
    [ exact OBJ | exact LSV | exact WIN | lia | lia
    | clear - SEPW LO; unhideL; lia
    | cbn [cells_size csize Nat.add length]; clear - SEPL LO; unhideL; lia
    | rewrite ?unsigned_lit by lia; exact ST
    | rewrite ?unsigned_lit by lia; clear - LO; lia
    | exact CEIL
    | rewrite ?unsigned_lit by lia; left; clear; lia
    | rewrite ?unsigned_lit by lia; clear - SEPW LO; unhideL; lia
    | rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add length]; clear - SEPL LO; unhideL; lia
    | assumption
    | exact ACc | exact AOc | clear - SPAL; unhideL; Z.div_mod_to_equations; lia | exact AWc | exact ALc | unhideL; exact LAL
    | ];
    clear ACc SKc AWc ALc AOc;
    lazymatch goal with H : rw_cells _ _ (bv_unsigned sp + -56) _ |- _ => rename H into OBJ end;
    lazymatch goal with H : rw_cells _ _ LST _ |- _ => rename H into LSV end;
    lazymatch goal with H : bytes_at _ _ SP _ |- _ => rename H into WIN end;
    lazymatch goal with H : stk _ _ lo _ |- _ => rename H into ST end
  end.

