Lemma vl_loop : forall (k i : nat) rax ra sp gp tp t0 t1 t2 a0x a1x a2 a3 a4 a5 a6 a7 s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (j8 : list byte)
    (F : bvmap 5 word) fc (m m1 : mem) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo shi : Z)
    (vp vl : Z) (pad7 : list byte),
  (length sbs - i <= k)%nat -> (0 < i <= length sbs)%nat ->
  vl_ctx m m1 sp s0v ra j8 LST SP sbs lrest lo shi (OptItCells LST (SP + Z.of_nat i) vp vl 0 pad7) -> vl_pure sp LST SP sbs lrest lo shi ->
  evt asegs (vl_post_v (opt_valid_from (S (length sbs - i)) true (skipn i (zbytes sbs)))
               ra sp gp tp s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LST SP sbs lrest lo shi m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz LST) s1 a0x a1x a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xd2ed8) fc None m1 (seg_rom asegs)).
Proof.
